import java.util.*;

public class CollectionDemo {
    public static void main(String[] args) {
        List<String> pipeline = new ArrayList<>();
        pipeline.add("Ingest");
        pipeline.add("Transform");
        pipeline.add("Persist");

        Set<String> uniqueStages = new HashSet<>(pipeline);
        uniqueStages.add("Ingest"); // Duplicate, ignored

        Map<String, Integer> stageLatencies = new HashMap<>();
        for (String stage : uniqueStages) {
            stageLatencies.put(stage, stage.length() * 42);
        }

        stageLatencies.forEach((k, v) -> 
            System.out.println("Stage: " + k + " | Latency: " + v + "ms")
        );
    }
}
